package com.sharkie.wobblekit;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.*;import android.view.*;import android.widget.*;import java.io.*;
public class MainActivity extends Activity {
 WobbleView view;Handler handler=new Handler();Runnable animation;static final String PREF="wobble";
 @Override public void onCreate(Bundle b){super.onCreate(b);LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(0xff15151c);LinearLayout bar=new LinearLayout(this);String[] labels={"Image","+ Zone","Play/Edit","Wallpaper"};for(int i=0;i<labels.length;i++){final int n=i;Button button=new Button(this);button.setText(labels[i]);button.setTextSize(11);bar.addView(button,new LinearLayout.LayoutParams(0,58,1));button.setOnClickListener(v->action(n));}root.addView(bar);view=new WobbleView(this);root.addView(view,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);loadSaved();animation=()->{view.tick();handler.postDelayed(animation,16);};handler.post(animation);}
 void action(int n){if(n==0){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("image/*");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,1);}else if(n==1){view.addZone();saveZones();}else if(n==2){view.editing=!view.editing;saveZones();Toast.makeText(this,view.editing?"Edit zones":"Boing! :3",0).show();}else{saveZones();Intent i=new Intent(android.app.WallpaperManager.ACTION_CHANGE_LIVE_WALLPAPER);i.putExtra(android.app.WallpaperManager.EXTRA_LIVE_WALLPAPER_COMPONENT,new ComponentName(this,WobbleWallpaper.class));startActivity(i);}}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==1&&result==RESULT_OK&&data!=null){try{android.net.Uri uri=data.getData();getContentResolver().takePersistableUriPermission(uri,Intent.FLAG_GRANT_READ_URI_PERMISSION);getPreferences(0).edit().putString("uri",uri.toString()).apply();loadSaved();}catch(Exception ex){Toast.makeText(this,ex.toString(),1).show();}}}
 void loadSaved(){try{String s=getPreferences(0).getString("uri",null);if(s!=null){InputStream in=getContentResolver().openInputStream(android.net.Uri.parse(s));Bitmap b=BitmapFactory.decodeStream(in);in.close();view.load(b);String z=getPreferences(0).getString("zones","");for(String item:z.split(";")){String[] p=item.split(",");if(p.length==3)view.zones.add(new WobbleView.Zone(Float.parseFloat(p[0]),Float.parseFloat(p[1]),Float.parseFloat(p[2])));}}}catch(Exception ignored){}}
 void saveZones(){StringBuilder b=new StringBuilder();for(WobbleView.Zone z:view.zones)b.append(z.x).append(',').append(z.y).append(',').append(z.r).append(';');getPreferences(0).edit().putString("zones",b.toString()).apply();}
 @Override protected void onPause(){saveZones();super.onPause();} @Override protected void onDestroy(){handler.removeCallbacks(animation);super.onDestroy();}
}
